/**
 * The access of one person to a space or a list ("Personnes ayant accès"), given by someone
 * who manages it. A space or a list holds 200 grants at most. The owner of the space holds
 * none: they always have `edit` ("Propriétaire").
 */
export interface Grant {
  /** Account of the person, a current member or guest of the organization. */
  userId: string;
  role: AccessRoleValue;
  /** When the person was given this role. */
  grantedAt: string;
  grantedBy: Actor;
}

/**
 * The role to give ("Droit d’accès"); it replaces the role the person had there.
 */
export interface GrantChange {
  role: AccessRole;
}

/**
 * `active` for a list of the sidebar, `archived` for a list of the archives ("Liste
 * archivée"), `deleted` for a deleted list ("Liste supprimée"), which comes back when one of
 * its tasks is restored. Later versions may add states (`x-extensible-enum`).
 */
export type ListStateValue = string;

/**
 * The list of an archived or trashed task, with its name and state as they are now.
 */
export interface ListRef {
  id: string;
  spaceId: string;
  /** "Nom", 80 characters at most. */
  name: string;
  state: ListStateValue;
}

/**
 * A list of the archives ("Archives", tab "Listes").
 */
export interface ArchivedList {
  list: TaskList;
  /**
     * Its top-level tasks, subtasks left out ("14 tâches").
     * @minimum 0
     */
  taskCount: number;
}

/**
 * A task of the archives ("Archives", tab "Tâches"): the root of a subtree archived together,
 * which comes back together.
 */
export interface ArchivedTask {
  task: TaskSummary;
  list: ListRef;
  /**
     * The subtasks archived with it, at every level.
     * @minimum 0
     */
  subtaskCount: number;
  /** "archivée le 5 nov." */
  archivedAt: string;
  archivedBy: Actor;
}

/**
 * One element of the trash ("Corbeille"): a task and its subtasks at every level, deleted
 * together, which come back or are erased together. Deleting a subtask makes an entry of its
 * own subtree; deleting a list or a space makes one entry per top-level task.
 */
export interface TrashEntry {
  id: string;
  task: TaskRef;
  /**
     * The parent the root had when it was deleted ("Sous-tâche de CAD-482"); `null` for a
     * top-level task.
     */
  parentKey: TaskKey | null;
  /**
     * The subtasks deleted with it, at every level ("Avec 3 sous-tâches").
     * @minimum 0
     */
  subtaskCount: number;
  list: ListRef;
  /** "Supprimée il y a 2 jours" */
  trashedAt: string;
  trashedBy: Actor;
  /**
     * When the entry is erased for good, 30 days after `trashedAt` ("Effacée définitivement
     * dans 28 jours").
     */
  purgeAt: string;
}

/**
 * What a restoration brought back ("CAD-452 restaurée", "Avec 2 sous-tâches, de retour dans
 * Sprint 14.").
 */
export interface TrashRestored {
  task: Task;
  list: TaskList;
  /**
     * The subtasks that came back with it, at every level.
     * @minimum 0
     */
  subtaskCount: number;
  /**
     * Whether the root left its parent, which is no longer live or can no longer take it
     * (", détachée de son parent supprimé"); it is then a top-level task.
     */
  detached: boolean;
  /** Whether its list, deleted, came back with it, at the end of its space. */
  listRestored: boolean;
  /** Whether the space of that list, deleted, came back too, at the end of the sidebar. */
  spaceRestored: boolean;
}

/**
 * What "Vider la corbeille" took out ("Corbeille vidée", "12 éléments effacés définitivement.").
 */
export interface TrashEmptied {
  /**
     * Entries that left the trash, to be erased for good.
     * @minimum 0
     */
  entryCount: number;
}

/**
 * A request for access ("Demander l’accès"): exactly one of `spaceId`, `listId` and
 * `taskKey`, as the link the caller followed names the target; none or several answer
 * `400 request.invalid`.
 */
export interface AccessRequestCreation {
  /** A space to have a role on. */
  spaceId?: string;
  /** A list to see. */
  listId?: string;
  taskKey?: TaskKey;
  /**
     * "Message pour Léa (facultatif)", trimmed; `null` or an empty text for none.
     * @maxLength 500
     * @nullable
     */
  message?: string | null;
}

/**
 * What a request asks for: `space`, `list` or `task`. Later versions may add targets
 * (`x-extensible-enum`).
 */
export type AccessRequestTargetValue = string;

/**
 * `pending` until someone who manages the target answers, then `approved` or `refused`. Later
 * versions may add states (`x-extensible-enum`).
 */
export type AccessRequestStateValue = string;

/**
 * A request for access, as the people who manage its target read it. The requester never
 * reads it: they learn the answer from the inbox (cadenway-notification-service). It has no
 * `version` of its own to send back: it changes once, from `pending`, and a second answer
 * gets `409 access-request.already-decided`; its events carry `1`, then `2`.
 */
export interface AccessRequest {
  id: string;
  target: AccessRequestTargetValue;
  /** The space of the target. */
  spaceId: string;
  /**
     * The list of a list or task target; `null` for a space.
     * @nullable
     */
  listId: string | null;
  /** The task of a task target, with its name and status as they are now; `null` otherwise. */
  task: TaskRef | null;
  requester: UserRef;
  /**
     * The message of the requester, 500 characters at most; `null` when there is none.
     * @nullable
     */
  message: string | null;
  state: AccessRequestStateValue;
  /** The role an approval gave; `null` while pending or when refused. */
  role: AccessRoleValue | null;
  createdAt: string;
  /**
     * When it was approved or refused; `null` while pending.
     * @nullable
     */
  decidedAt: string | null;
  /** Who approved or refused it; `null` while pending. */
  decidedBy: Actor | null;
}

/**
 * The role an approval gives the requester ("Droit d’accès").
 */
export interface AccessRequestApproval {
  role: AccessRole;
}

/**
 * Members specific to the code, for example the fields that failed validation.
 */
export type ProblemDetails = { [key: string]: unknown };

/**
 * RFC 9457 problem with the Cadenway extensions `code` and `details`.
 */
export interface Problem {
  /** URI reference that identifies the problem type. */
  type: string;
  /** Short summary of the problem type, the same for every occurrence. */
  title: string;
  /** HTTP status of the response. */
  status: number;
  /** Explanation specific to this occurrence. */
  detail?: string;
  /** URI reference that identifies this occurrence. */
  instance?: string;
  /** Stable machine code, `<domain>.<reason>`. */
  code: string;
  /** Members specific to the code, for example the fields that failed validation. */
  details?: ProblemDetails;
}

/**
 * `onboarding.wizard-closed`: the wizard has already finished or was dismissed.
 */
export type OnboardingWizardClosedResponse = Problem;

/**
 * `onboarding.checklist-unavailable`: the caller has no provisioned space for this change.
 */
export type OnboardingChecklistUnavailableResponse = Problem;

/**
 * - `onboarding.wizard-closed`: this wizard was already finished or dismissed;
 * - `space.prefix-taken`: the prefix is reserved in the organization, given in `details.prefix`;
 * - `idempotency.request-in-progress`: a matching request with this key is still running.
 */
export type OnboardingFinishConflictResponse = Problem;

/**
 * - `organization.role-forbidden`: for finish only, the caller cannot create a space;
 * - `auth.scope-missing`: the personal API token lacks `tasks:write`;
 * - `organization.not-selected`, `organization.mfa-required`: see `TasksReadForbidden`;
 * - `auth.csrf-rejected`: the `Origin` or the `Content-Type` of the request is refused.
 */
export type OnboardingWriteForbiddenResponse = Problem;

/**
 * `idempotency.key-reused`: the key was used with a different body.
 */
export type OnboardingIdempotencyKeyReusedResponse = Problem;

/**
 * `request.version-mismatch`: `details.version` is the current onboarding version to read again.
 */
export type OnboardingVersionMismatchResponse = Problem;

/**
 * `task.archived` or `idempotency.request-in-progress`.
 */
export type TaskDuplicateConflictResponse = Problem;

/**
 * `task.archived`, `recurrence.already-spawned`, `idempotency.request-in-progress`.
 */
export type BulkConflictResponse = Problem;

/**
 * `task.not-found`, `task.trashed`, `list.not-found`, `organization.not-found`.
 */
export type BulkTargetNotFoundResponse = Problem;

/**
 * `bulk.expansion-limit-reached`, `idempotency.key-reused`, `task.status-hidden`, `task.cancel-reason-required`, `task.cancel-reason-unexpected`, `task.assignee-invalid`, `task.assignee-limit-reached`, `task.subtask-limit-reached`, `task.subtask-depth-exceeded`, `task.start-date-invalid`, `milestone.status-invalid`, `milestone.dates-invalid`, `recurrence.date-out-of-range`.
 */
export type BulkRefusedResponse = Problem;

/**
 * `task.subtask-limit-reached`, `task.subtask-depth-exceeded`, `task.status-hidden`, `task.cancel-reason-required`, `idempotency.key-reused`.
 */
export type TaskDuplicateRefusedResponse = Problem;

/**
 * `dependency.not-found`, `task.not-found`, `task.trashed`, `organization.not-found`.
 */
export type DependencyNotFoundResponse = Problem;

/**
 * `dependency.already-exists`, `task.archived`, `idempotency.request-in-progress`.
 */
export type DependencyConflictResponse = Problem;

/**
 * `dependency.cycle`, `dependency.limit-reached`, `idempotency.key-reused`.
 */
export type DependencyRefusedResponse = Problem;

/**
 * `task.archived`: a task is archived; `recurrence.already-spawned`: the source already has a successor.
 */
export type TaskRecurrenceConflictResponse = Problem;

/**
 * `request.version-mismatch`: If-Match is not the current comment version; `details.version` is.
 */
export type CommentVersionMismatchResponse = Problem;

/**
 * `access.role-insufficient`, `auth.scope-missing`, `auth.csrf-rejected`, `organization.not-selected`, `organization.mfa-required`.
 */
export type CollabRoleResponse = Problem;

/**
 * `access.role-insufficient`, `comment.author-required`, `auth.scope-missing`, `auth.csrf-rejected`, `organization.not-selected`, `organization.mfa-required`.
 */
export type CollabAuthorResponse = Problem;

/**
 * `comment.not-found`, `task.not-found`, `task.trashed`, `organization.not-found`.
 */
export type CollabCommentNotFoundResponse = Problem;

/**
 * `task.archived`, `idempotency.request-in-progress`.
 */
export type CollabCreateConflictResponse = Problem;

/**
 * `mention.recipient-invalid`.
 */
export type CollabMentionResponse = Problem;

/**
 * `mention.recipient-invalid`, `idempotency.key-reused`.
 */
export type CollabCreateRefusedResponse = Problem;

/**
 * `watcher.recipient-invalid`, `watcher.limit-reached`.
 */
export type CollabWatcherRefusedResponse = Problem;

/**
 * The request does not match the schema: `request.invalid`, with one `details.issues` entry
 * per failed member (`path` is the dotted path of the member, empty for the body itself, the
 * name of the header for a header). A change of `description` without `If-Match` answers it
 * with an issue `{ in: header, path: If-Match, code: required }`.
 */
export type BadRequestResponse = Problem;

/**
 * - `auth.session-required`: the request carries neither a session cookie nor a bearer token;
 * - `auth.session-expired`: the cookie names a session that ended;
 * - `auth.api-token-invalid`: the bearer token is unknown, revoked or expired, or its user
 *   no longer belongs to its organization.
 */
export type UnauthenticatedResponse = Problem;

/**
 * - `auth.scope-missing`: the personal API token lacks `tasks:read`; `details.requiredScopes`
 *   lists what the route needs;
 * - `organization.not-selected`: the session has no current organization;
 * - `organization.mfa-required`: the authentication policy of the organization requires
 *   two-step verification for the role of the caller, who has none; `details.organizationId`
 *   names it.
 */
export type TasksReadForbiddenResponse = Problem;

/**
 * - `access.role-insufficient`: the caller sees the list of the task, or the list a move
 *   goes to, without `edit` on it; `details.role` is their role there, `details.requiredRole`
 *   is `edit`;
 * - `auth.scope-missing`: the personal API token lacks `tasks:write`;
 * - `organization.not-selected`, `organization.mfa-required`: see `TasksReadForbidden`;
 * - `auth.csrf-rejected`: the `Origin` or the `Content-Type` of the request is refused.
 */
export type TasksWriteForbiddenResponse = Problem;

/**
 * `organization.not-found`: the caller no longer belongs to the current organization, or, for a
 * few seconds after they joined it, task-service does not know them yet.
 */
export type OrganizationNotFoundResponse = Problem;

/**
 * - `list.not-found`: no list with this id that the caller sees;
 * - `organization.not-found`: see `OrganizationNotFound`.
 */
export type ListNotFoundResponse = Problem;

/**
 * - `approval.reviewer-required` applies when an editor was omitted from the round.
 * - `access.role-insufficient` applies when the actor has a list role below `edit`.
 * - See `TasksWriteForbidden` for `auth.scope-missing`, `auth.csrf-rejected`,
 *   `organization.not-selected` and `organization.mfa-required`.
 */
export type ApprovalVoteForbiddenResponse = Problem;

/**
 * - `approval.round-not-found` applies when the supplied ID differs from the current round or the task has no round.
 * - See `TaskNotFound` for `task.not-found`, `task.trashed` and `organization.not-found`.
 */
export type ApprovalRoundNotFoundResponse = Problem;

/**
 * - An archived task returns `task.archived`.
 * - A milestone returns `approval.milestone-unsupported`.
 */
export type ApprovalRoundConflictResponse = Problem;

/**
 * - An archived task returns `task.archived`.
 * - A milestone returns `approval.milestone-unsupported`.
 * - An existing vote returns `approval.vote-already-recorded`. Withdraw it before casting another.
 * - The automated completion returns `recurrence.already-spawned` if it would repeat an occurrence.
 */
export type ApprovalVoteConflictResponse = Problem;

/**
 * A requested reviewer without edit access causes `approval.reviewer-invalid`.
 */
export type ApprovalReviewersRefusedResponse = Problem;

/**
 * - `task.status-hidden` applies if the automatic status is unavailable in the task's space.
 * - `task.subtask-limit-reached` applies if the recurrence successor would exceed the parent capacity.
 * - `recurrence.date-out-of-range` applies if the successor dates are out of range.
 */
export type ApprovalTransitionRefusedResponse = Problem;

/**
 * - `task.not-found`: no task with this key that the caller sees, or a task in the trash
 *   that the caller could not change;
 * - `task.trashed`: the task is in the trash and the caller could change its list ("Tâche
 *   supprimée"). `details.key` and `details.name` name the task, `details.entryId` is the
 *   trash entry it belongs to (`POST /v1/trash/entries/{entryId}/restore`),
 *   `details.rootKey` the root of that entry, `details.trashedAt` and `details.trashedBy`
 *   (an `Actor`) say when and by whom it was deleted, `details.purgeAt` when it is erased
 *   ("Elle reste 30 jours dans la corbeille avant d’être effacée.");
 * - `organization.not-found`: see `OrganizationNotFound`.
 */
export type TaskNotFoundResponse = Problem;

/**
 * - `checklist-item.not-found`: the task has no item with this id;
 * - `task.not-found`, `task.trashed`, `organization.not-found`: see `TaskNotFound`.
 */
export type ChecklistItemNotFoundResponse = Problem;

/**
 * `idempotency.request-in-progress`: a request with the same `Idempotency-Key` still runs.
 */
export type RequestInProgressResponse = Problem;

/**
 * `task.archived`: the task is archived, or the parent the patch names is; `details.key`
 * names the archived task. It changes again once restored
 * (`POST /v1/tasks/{taskKey}/unarchive`, `openapi/public/archives.yaml`).
 */
export type TaskArchivedResponse = Problem;

/**
 * - `task.archived`: the parent is archived; `details.key` names it;
 * - `idempotency.request-in-progress`: a request with the same `Idempotency-Key` still runs.
 */
export type SubtaskCreationConflictResponse = Problem;

/**
 * - `task.archived`: the task is archived; `details.key` names it;
 * - `idempotency.request-in-progress`: a request with the same `Idempotency-Key` still runs.
 */
export type ChecklistItemConflictResponse = Problem;

/**
 * - `task.status-hidden`: the space of the list no longer uses the status; `details.status`
 *   names it;
 * - `task.cancel-reason-required`: the status `cancelled` without `cancelReason`;
 * - `task.cancel-reason-unexpected`: `cancelReason` or `cancelNote` with another status;
 * - `task.assignee-invalid`: an assignee is not a current member of the organization, or is a
 *   guest; `details.userIds` lists them;
 * - `task.start-date-invalid`: `startDate` without `dueDate`, or after it;
 * - `idempotency.key-reused`: the `Idempotency-Key` was sent before with another body;
 * - `mention.recipient-invalid`: a description mention recipient is ineligible;
 * - `milestone.status-invalid`: the final milestone status is invalid;
 * - `milestone.dates-invalid`: the final milestone dates or estimate are invalid.
 */
export type TaskCreationRefusedResponse = Problem;

/**
 * - `task.subtask-depth-exceeded`: the parent is at the third level;
 * - `task.subtask-limit-reached`: the parent has 25 subtasks;
 * - `task.status-hidden`, `task.cancel-reason-required`, `task.cancel-reason-unexpected`,
 *   `task.assignee-invalid`, `task.start-date-invalid`, `idempotency.key-reused`: see
 *   `TaskCreationRefused`.
 */
export type SubtaskCreationRefusedResponse = Problem;

/**
 * - `task.status-hidden`: the space no longer uses the status, which the task does not have;
 *   `details.status` names it;
 * - `task.cancel-reason-required`: the task becomes or stays `cancelled` without a reason;
 * - `task.cancel-reason-unexpected`: `cancelReason` or `cancelNote` for a task that is not
 *   `cancelled` after the patch;
 * - `task.start-date-invalid`: a start date without a due date, or after it;
 * - `task.list-invalid`: the list does not exist or the caller does not see it, or is not the
 *   list of the new parent;
 * - `task.parent-invalid`: the parent is unknown, not seen, the task itself or one of its
 *   subtasks; `details.parentKey` repeats it;
 * - `task.subtask-depth-exceeded`: the task and its subtasks would go beyond 3 levels;
 * - `task.subtask-limit-reached`: the parent has 25 subtasks;
 * - `mention.recipient-invalid`: a description mention recipient is ineligible;
 * - `milestone.status-invalid`: the final milestone status is invalid;
 * - `milestone.dates-invalid`: the final milestone dates or estimate are invalid;
 * - `recurrence.date-out-of-range`: the successor date cannot be represented;
 * - `custom-field.value-invalid`: a field is absent, retired or outside the resulting space,
 *   the value has the wrong type or the designated sprint points value is negative.
 */
export type TaskChangeRefusedResponse = Problem;

/**
 * - `task.assignee-invalid`: the person is not a current member of the organization, or is a
 *   guest; `details.userIds` names them;
 * - `task.assignee-limit-reached`: the task has 20 assignees.
 */
export type AssigneeRefusedResponse = Problem;

/**
 * `task.label-limit-reached`: the task has 20 labels.
 */
export type LabelLimitReachedResponse = Problem;

/**
 * - `task.checklist-limit-reached`: the checklist holds 100 items;
 * - `idempotency.key-reused`: the `Idempotency-Key` was sent before with another body.
 */
export type ChecklistItemRefusedResponse = Problem;

/**
 * `request.version-mismatch`: `If-Match` is not the current version of the task; `details.version` is.
 */
export type VersionMismatchResponse = Problem;

/**
 * `organization.context-changed`: `If-Organization-Match` differs from the organization
 * verified for this request. The problem omits `details` and gives no information about the
 * organizations or the task.
 */
export type OrganizationContextChangedResponse = Problem;

/**
 * - `organization.context-changed`: `If-Organization-Match` differs from the organization
 *   verified for this request. The problem omits `details` and gives no information about
 *   the organizations or the task. The response has `Cache-Control: private, no-store`.
 * - `request.version-mismatch`: `If-Match` differs from the current task version, given in
 *   `details.version`.
 */
export type TaskUpdatePreconditionFailedResponse = Problem;

/**
 * `rate-limit.exceeded`: the gateway refuses more requests from this session or token for now.
 */
export type RateLimitedResponse = Problem;

/**
 * task-service cannot answer: `upstream.unavailable`, `upstream.unreachable`,
 * `upstream.timeout`, `upstream.circuit-open`, `upstream.failed`, `upstream.unauthorized` or
 * `upstream.deadline-exceeded`, with `details.service`.
 */
export type UnavailableResponse = Problem;

export type DependencyDirectionParameter = DependencyDirection;

/**
 * The strong task version ETag last returned on the task or approval state.
 */
export type ApprovalIfMatchParameter = string;

/**
 * `"<version>"` of the task the change was made from, as the `ETag` gave it.
 */
export type IfMatchParameter = string;

/**
 * The UUIDv7 of the organization the caller expects, compared without regard to hex case.
 * The verified session or API token determines the organization for the request. The gateway
 * uses this header only to check that organization before calling task-service. A mismatch
 * answers `412 organization.context-changed`. Omit the header to use the verified context
 * without an organization precondition. Send exactly one UUIDv7: repeated, comma-separated
 * or malformed values answer `400 request.invalid` with an issue on this header.
 */
export type IfOrganizationMatchParameter = string;

/**
 * Key of this creation, chosen by the client, a UUID for example; the same key with the same
 * body within 24 hours answers what the first request answered.
 */
export type IdempotencyKeyParameter = string;

/**
 * The date of the caller, in their time zone, which task-service does not know: the late
 * tasks, the tasks due that day and the current sprints are counted against it.
 */
export type TodayParameter = string;

/**
 * Statuses to keep, separated by commas.
 */
export type StatusFilterParameter = StatusKey[];

/**
 * Priorities to keep, separated by commas.
 */
export type PriorityFilterParameter = PriorityKey[];

/**
 * Assignees to keep, separated by commas: account ids, `me` for the caller, `none` for the
 * tasks nobody is assigned.
 */
export type AssigneeFilterParameter = string[];

/**
 * Labels to keep, separated by commas, without regard to case.
 */
export type LabelFilterParameter = string[];

/**
 * Text to find, without regard to case or accents.
 */
export type SearchParameter = string;

/**
 * Keep the tasks due on or after this date.
 */
export type DueFromParameter = string;

/**
 * Keep the tasks due on or before this date.
 */
export type DueToParameter = string;

